def grade(score):
    if not isinstance(score, (int, float)):
        return '分数无效'
    if score < 0 or score > 100:
        return '分数无效'
    if score >= 90:
        return '优秀'
    elif score >= 80:
        return '良好'
    elif score >= 60:
        return '及格'
    else:
        return '不及格'

for s in (95, 83, 60, 59, 120):
    print(s, grade(s))
